function Modal({title,children,onClose,wide=false,authDialog=false,closeLabel='Close'}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean;authDialog?:boolean;closeLabel?:string}){
 const ref=useRef<HTMLDialogElement>(null);
 const titleId=useId();
 useEffect(()=>{
  ref.current?.showModal();
  const previousOverflow=document.body.style.overflow;
  document.body.style.overflow='hidden';
  return()=>{document.body.style.overflow=previousOverflow};
 },[]);
 return <dialog ref={ref} aria-labelledby={titleId} className={'dialog'+(wide?' wide':'')+(authDialog?' makan-auth':'')} onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose()}}>
  <div className={'dialog-head'+(authDialog?' makan-pattern':'')}>
   <div>{authDialog&&<MakanLogo/>}<h2 id={titleId}>{title}</h2></div>
   <button className="icon-btn" aria-label={closeLabel} onClick={onClose}><X size={20}/></button>
  </div>
  {children}
 </dialog>
}
