function date(s:string,lang:Language){return new Intl.DateTimeFormat(lang==='ar'?'ar-SY':'en-GB',{day:'numeric',month:'short'}).format(new Date(s))}
function safeImage(url:string|undefined){if(!url)return '';try{const u=new URL(url,'https://local.invalid');return u.protocol==='https:'||u.origin==='https://local.invalid'?url:''}catch{return ''}}

