 {(view==='privacy'||view==='terms')&&<section className="container legal-page"><span className="eyebrow">{t('وثائق المنصة','PLATFORM DOCUMENTS')}</span><h1>{view==='privacy'?t('الخصوصية والبيانات','Privacy & data'):t('شروط استخدام المنصة','Platform terms')}</h1><div className="message"><FileText size={19}/>{t('مسودة للمراجعة قبل الإطلاق العام. لم تُعتمد الشروط القانونية النهائية بعد.','Draft for review before public launch. Final legal terms have not been approved.')}</div>{(view==='privacy'?[[t('ما يجمعه الحساب','Account information'),t('يُحفظ الاسم والبريد الإلكتروني ورقم الهاتف الذي تضيفه، مع العقارات المحفوظة والاستفسارات المرسلة.','We store your name, email, phone number if provided, saved properties and submitted inquiries.')],[t('مشاركة الاستفسارات','Sharing inquiries'),t('عند إرسال استفسار، تُشارك معلومات التواصل والرسالة مع الوكيل المسؤول ومدير مكتبه ومدير المنصة حسب الصلاحيات.','When you submit an inquiry, its contact details and message are shared with the responsible agent, their office manager and platform administrators according to their permissions.')],[t('الحساب والطلبـات','Account requests'),t('يمكن تعديل الاسم ورقم الهاتف من صفحة حسابي. يجب تحديد جهة التواصل المسؤولة عن طلبات حذف البيانات قبل الإطلاق العام.','You can edit your name and phone in My account. A responsible contact for data deletion requests must be established before public launch.')]]:[[t('دور المنصة','Role of the platform'),t('بيت يسهّل عرض العقارات والتواصل بشأنها. يجب التحقق من الملكية والمستندات وتفاصيل أي اتفاق بشكل مستقل.','MAKAN facilitates property discovery and communication. Ownership, documents and the details of any agreement must be independently verified.')],[t('دقة الإعلانات','Listing accuracy'),t('المعلن مسؤول عن دقة بيانات العقار وحقوق الصور. مراجعة الإعلان ليست ضماناً للملكية أو الحالة القانونية للعقار.','Advertisers are responsible for accurate property information and image rights. Listing review is not a guarantee of ownership or legal status.')],[t('المعاينة','Preview content'),t('المحتوى التجريبي والصور التصورية معروضة لتقييم التصميم فقط وليست عروض بيع أو إيجار فعلية.','Demo content and concept images are for design evaluation and are not actual offers to sell or rent.')]]).map(([title,body])=><div key={title}><h2>{title}</h2><p>{body}</p></div>)}</section>}
